def solve2(g):
    cnt=Counter(v for r in g for v in r)
    block=cnt.most_common(1)[0][0]
    H,W=len(g),len(g[0])
    lr=[i for i in range(H) if all(g[i][j]!=block for j in range(W))]
    lc=[j for j in range(W) if all(g[i][j]!=block for i in range(H))]
    M=[[g[lr[i]][lc[j]] for j in range(len(lc))] for i in range(len(lr))]
    n,m=len(M),len(M[0])
    seg=Counter()
    for i in range(H):
        if i not in lr:
            for j in lc: seg[g[i][j]]+=1
    for j in range(W):
        if j not in lc:
            for i in lr: seg[g[i][j]]+=1
    lattice=seg.most_common(1)[0][0] if seg else None
    bg=block
    NR,NC=n-1,m-1
    out=[[bg]*NC for _ in range(NR)]
    seen=set()
    for i in range(n):
        for j in range(m):
            if M[i][j] in (lattice,bg) or (i,j) in seen: continue
            comp=[(i,j)]; seen.add((i,j)); st=[(i,j)]
            while st:
                a,b=st.pop()
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<n and 0<=y<m and (x,y) not in seen and M[x][y]==M[i][j]:
                        seen.add((x,y)); comp.append((x,y)); st.append((x,y))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            for r in range(min(rs),max(rs)):
                for c in range(min(cs),max(cs)):
                    if 0<=r<NR and 0<=c<NC: out[r][c]=M[i][j]
    rows=[i for i in range(NR) if any(v!=bg for v in out[i])]
    cols=[j for j in range(NC) if any(out[i][j]!=bg for i in range(NR))]
    if not rows: return []
    return [r[cols[0]:cols[-1]+1] for r in out[rows[0]:rows[-1]+1]]
